#!/usr/bin/env node
/**
 * EVERY GENERATED FILE STAMPED FROM A CONTRACT CARRIES THAT CONTRACT'S CURRENT VERSION.
 *
 * ─── WHY (GEN-046, item 3) ───────────────────────────────────────────────────
 *
 * `GEN-042` bumped `resident-mobile/severity.json` to 0.4.0 and regenerated
 * nothing. Two consumers in two apps kept stamping 0.3.4 for three PIDs.
 * `apps/management-web` was caught only when `GEN-046` went looking for a gate to
 * install; `apps/resident-portal` was not caught at all — its own
 * `severity-tokens.test.ts` had been red the whole time and no gate ran it.
 *
 * RULED: the PID that bumps a contract regenerates EVERY `*.g.ts` consumer of it,
 * in every app. This is the check that makes forgetting impossible, and it belongs
 * to the API track because the BUMP does — the file is generated, so which app it
 * happens to live in decides nothing about who broke it.
 *
 * ─── DERIVED, NOT LISTED ─────────────────────────────────────────────────────
 *
 * `[correlated-lists-certify-nothing]`: a hand-kept list of consumers would have
 * omitted exactly the consumer that was stale, because the person who forgot to
 * regenerate it is the person who would have kept the list. So the subject is
 * discovered by walking `apps/<app>/src` for `*.g.ts`, and each file names its own
 * source in its generated header:
 *
 *   // Generated by <tool> from <path>.
 *
 * Where that path is a JSON carrying `contractVersion`, every `*_CONTRACT_VERSION`
 * stamp in the file must equal it. Files generated from a fixture DIRECTORY rather
 * than a contract are out of scope here and named in the output, so the number this
 * check covers is never mistaken for the number that exist.
 */
import { readFileSync, readdirSync, existsSync, statSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve, join, relative } from 'node:path';

const REPO = resolve(dirname(fileURLToPath(import.meta.url)), '../../..');

// A generated consumer is `.g.ts` OR `.g.dart` (GEN-056): the Flutter app is a
// consumer of the same contracts, and a check that walked only TypeScript let its
// severity tokens stamp 0.2.2 for a month. The file type is discovered, not listed.
const walk = (dir, out = []) => {
  if (!existsSync(dir)) return out;
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    const p = join(dir, e.name);
    if (e.isDirectory()) { if (e.name !== 'node_modules' && e.name !== 'dist') walk(p, out); }
    else if (e.name.endsWith('.g.ts') || e.name.endsWith('.g.dart')) out.push(p);
  }
  return out;
};

/**
 * A generated file names its own source and stamps its own version, in whichever
 * language it is written. Both are DISCOVERED from the file, never a second list.
 *   .g.ts   : `Generated by <tool> from <path>.json` + `export const X_CONTRACT_VERSION = "v";`
 *   .g.dart : `// Source: <path>.json`                + `static const contractVersion = 'v';`
 */
const readConsumer = (src, isDart) => {
  const head = src.split('\n').slice(0, 6).join(' ');
  const m = isDart
    ? /Source:\s+([A-Za-z0-9._/-]+\.json)/.exec(head)
    : /from\s+([A-Za-z0-9._/-]+\.json)/.exec(head);
  const stamps = isDart
    ? [...src.matchAll(/static const (contractVersion) = '([^']+)';/g)]
    : [...src.matchAll(/^export const ([A-Z0-9_]*CONTRACT_VERSION) = "([^"]+)";/gm)];
  return { source: m ? m[1] : undefined, stamps };
};

const apps = existsSync(join(REPO, 'apps'))
  ? readdirSync(join(REPO, 'apps'), { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name)
  : [];

const failures = [];
let checked = 0;
const skipped = [];

for (const app of apps) {
  // `.g.ts` live under src, `.g.dart` under lib (a Flutter app has no src).
  for (const file of [...walk(join(REPO, 'apps', app, 'src')), ...walk(join(REPO, 'apps', app, 'lib'))]) {
    const rel = relative(REPO, file);
    const isDart = file.endsWith('.g.dart');
    const src = readFileSync(file, 'utf8');
    const { source, stamps } = readConsumer(src, isDart);
    if (stamps.length === 0) continue;

    if (!source) { skipped.push(`${rel} (stamped, but its header names no contract JSON)`); continue; }
    const contractPath = join(REPO, source);
    if (!existsSync(contractPath) || !statSync(contractPath).isFile()) {
      failures.push(`${rel}\n        names ${source}, which does not exist`); continue;
    }
    let contract;
    try { contract = JSON.parse(readFileSync(contractPath, 'utf8')); }
    catch { failures.push(`${rel}\n        names ${source}, which is not readable JSON`); continue; }
    const want = contract.contractVersion;
    if (want === undefined) { skipped.push(`${rel} (${source} declares no contractVersion)`); continue; }

    checked++;
    const regen = isDart
      ? `node tool/generate-*.mjs from apps/${app}`
      : `pnpm -C apps/${app} run generate`;
    for (const [, name, got] of stamps) {
      if (got !== want) {
        failures.push(
          `${rel}\n        ${name} = "${got}" but ${source} is now "${want}"\n` +
          `        the contract moved and this consumer did not — regenerate it (${regen})`);
      }
    }
  }
}

// VACUITY REFUSAL. A check that covers nothing passes forever and means nothing;
// this one covered zero files for the whole time the bug it exists for was live.
if (checked === 0) {
  console.log('  FAIL  no generated file was checked against a contract — this guard is vacuous');
  process.exit(1);
}

if (failures.length > 0) {
  console.log(`  FAIL  ${failures.length} generated file(s) stamped from a stale contract`);
  for (const f of failures) console.log(`        ${f}`);
  process.exit(1);
}
console.log(`  ok     every generated file matches its contract          ${checked} stamped file(s)`
  + (skipped.length ? `, ${skipped.length} not contract-derived` : ''));
